"""Pin bounded player history and airborne counter evidence, static only."""
import csv,hashlib,json
from pathlib import Path
from inventory_rom import ROM_HASH
from m68k_static import Decoder
def catalogue(project):
    rom=(project/'local/rolo.md').read_bytes()
    if hashlib.sha256(rom).hexdigest()!=ROM_HASH:raise ValueError('ROM mismatch')
    inv=json.loads((project/'docs/stage9/inventory.json').read_text(encoding='utf-8'))
    accepted={a for r in inv['routines'] for a in r['blocks']}
    operations=[]
    scroll_commands=[int.from_bytes(rom[0x6a26+i*4:0x6a2a+i*4],'big') for i in range(32)]
    if scroll_commands!=[0x70000003+i*0x200000 for i in range(32)]:raise ValueError('Scroll command literals differ')
    if list(rom[0x924c:0x9250])!=[0,1,2,3] or list(rom[0x9472:0x9476])!=[0,1,2,1]:raise ValueError('Surface data literals differ')
    for start,end,name,contract,pending in [
        (0xfcd4,0xfd44,'Live actor animation-list prefix','F280FF; cursor98C8 live active keys,eachactorA5 anddefinitionA4 capturedbeforecallback. Definition7bit5 calls actor42 with A6/A5/A4preserved, so definition identity staysold but bytes remainlive. Unless definitiontype18 ordefinition26bit6, parent76 copiesintegerX/Y,selector70,facing118,directions121/122; fractionsretained. Originaldefinition18tablezero skipsinnerFD44. Native outerloop and explicitdefinition-key innerselection preservecallback mutation distinction.', 'All callback/definition mutation domains, RAM definition storage stability, active-list termination, complete animation control/program union and SDL binding remain incomplete.'),
        (0xfe0a,0xfe1e,'Live actor animation-list tail','Readnextlong activekey thenadvancecursor, nonzero branchesFCE4. Terminal restores display accessA6=C00000 thenF280bytezero andRTS. Native typedoperations use no hardwareport register cursor; F280zero onlyafterterminal.', 'Full nativegraphicsqueue useofF280, exceptions/unsupported domains and independentoriginal sequence remain incomplete.'),
        (0x6960,0x6a26,'Horizontal scroll publication','SampleF286mode,write8B00|mode and8F02 beforedispatch4slots.0writesF324/F350pairatF000;1literal69A8return.2latchesF324 highword once,reads32live7440words,NEGword lowbackground, writes32pairs throughliteral6A26commandsatF000+16n.3requests512words7440→F000via2468. Native typedstorage handles0/1/2; mode3requiresqueue binding.', 'AllF286writerdomains,7440producers/updates, graphics queue timing and fullrenderer/per-line adoption, independent original-reference remain incomplete.'),
        (0x6aa6,0x6ac6,'Vertical scroll publication','Set8F02increment2,write40000010command,VSRAMpairF326/F352, bothvalues sampled beforewrites. Native typedverticalpair doesnotdependonhardwareportstate.', 'Original VSRAMcolumnmode domains, renderer vertical application and shared frame/display timing remain incomplete.'),
        (0x2f3c,0x2ff6,'Four-bank palette flash counters','DecrementF2BAword; nonnegative returns, negative reload10. For each liveF2B5..F2B8 counter: zero skips; decrementbyte, odd choosescommon4B7CA, even RAMC5EE+bank32; transfer15words through2468 toCRAMbyte2+bank32, leavescolour0. Lastbank falls through2FE8 helper beforeRTS. Native requests preserveorder andlaterbank reads afterservice.', '2468 queue/capture/interrupt timing, RAM palette sources/writers and renderer palette adoption, all counter domains and independent original colours remain incomplete.'),
        (0x1c6c,0x1cee,'Complete normal level-frame call order','PublishC466=1C6C beforeprefix5C58,260A,25A8,2F3C,6960,6AA6. Middle7748,8C88,29EE,A808,785C,6796,881C,9196,8838,925C. Suffix4D54,948A,FCD4,FAA0,5060,5348,31D6,2C4C,7292,72A2,5CE6,9534 thenRTS. Existing native ScheduledPlayerFrameServices implements middle service bindings, not full normal-frame driver.', 'Prefix/suffix native service composition, startup/shared-state domains, callbacks/animation/spawn/display/timing and SDL adoption remain incomplete.'),
        (0x8c88,0x8d8e,'Type8 post-motion terrain mutation','Type8 and actor53 gate; clear53,sound0C before livebankF2F8 read.8D8E pair picksfacing118bit3 offset; negative returns. SampleXY±8/-8 into1024pixel64x64ring; searchcount+1 records8bytes usingtile&1FF. Matchwriteslower/upperquadpatterns unmodified thenreplacement|oldFE00flags tobacking; upper parallelmetadataword+8192 becomes signedoffset fromliveF32C, finalMAPwordfromtable. Native storage separatesdata/display services.', 'All bank domains, negative count/table reads, liveF30A/F32C mapping, shared display timing and original comparison remain incomplete.'),
        (0x92f2,0x9420,'Trigger dispatch and transitions','18verifiedbranchslots:0checkpoint93FE requirescontrolledtype4;1effect9420,2type12snap9434,3action9476,4literalRTS9486,5..15literalRTS9488,16selector933A,17relocation937A.933AwritesF2F6=param&127,F26C=parambit7,F26D/C522FF,sound1D.937Adestination3EE4negativefails; sound1D then63FA while preservingD6/D7; resolve livecontrolled,writeX/Y/fractionszero/directionszero/speedszero;684E,6864,4CB8,7292,72A2,6960,6AA6,31D6,25A8,66DE;type4AC34.', 'Destination3EE4 implementation and ordered reset/history/camera/graphics/state services, callback/global mutations and independent original reference remain incomplete.'),
        (0x9486,0x9488,'Trigger slot4 literal return','9486literalRTS, distinct entry from9488.', 'Full caller ordering and independent original reference remain incomplete.'),
        (0x2838,0x2860,'Trigger pool initialization','Sixteen 16-byte records at6936..6A36exclusive, 17-long free stack68F2 with zero terminal and cursor68EE; clear sentinel long6A36 only, record contents retained.', 'Complete startup caller/reset domains and independent original snapshots remain incomplete.'),
        (0x4a84,0x4b2e,'Trigger allocation and release','4A84 pops free cursor68EE, inserts node at6A36 doubly linked head, X=D3 Y=D6ASL3, offset8=D0 param10=D4 consume11=D2 marker12=D1 oldmarker14 saved before marker byte0x17 (class23decimal, NOTdestinationclass0x11). 4B00 unlinks and pushes node while retaining record bytes/links. 4ADC restores marker and preserves A1;4AF4 MOVEM saveA1/D0 restoreD0/D1 leaves free-stack cursor A1 visible.', 'Class8 Level1 MAP binding exists; other families, duplicate-release reaching domains, dispatch mutations and independent reference remain incomplete.'),
        (0x925c,0x92f2,'Controlled trigger scan','Latched controlled X/Y, signed wrapped reference bounds X-170..X+420 Y-F0..Y+2C0. Live nextword2 traversal from6A36; outside release4ADC, inclusive17x17 activation, consume11 invokes4AF4 changing lowerX A1 to free-stack cursor; dispatchword8 selects92F2 table and then reads live retained next link.', '18-slot dispatch bodies and all selector domains, marker mutations/frame ordering and independent original comparison remain incomplete.'),
        (0x920a,0x924c,'Surface slot4 acceleration/animation','Drag300, override800. Direction121 XOR facing118 bit3 selects zero index or speed58word signed cappedabove3. Raw924C bytes0,1,2,3 become actor115. Native rejects negative speed-word read-domain after publishingdrag/override.', 'Negative speed-word reaching domain and adjacent-ROM byte reads, independent original reference remain incomplete.'),
        (0x9250,0x925c,'Surface slot2 gate','C5E8zero branches9476 action latch; nonzero RTS.', 'C5E8 producer/caller domain and independent original reference remain incomplete.'),
        (0x9420,0x9472,'Surface effect/type12 snap','9420setsC516FF andactor125bit2.9434controlledtype!=12uses9420; type12clears124bit4,setbit0,clearsverticalspeed62,alignsYFFF0andADDBbobindexed(C490ASR3)&3 using9472 bytes0,1,2,1; lowYfraction untouched.', 'Frame/global producer domains, native loop binding and independent original reference remain incomplete.'),
        (0x9476,0x9486,'Surface action latch','IfC512zero setC517FF; otherwise unchanged.', 'Shared contact/frame mutation ordering and independent original reference remain incomplete.'),
        (0x9488,0x948a,'Surface slots6/7 literal return','Bothtable slots target9488 literalRTS; no sideeffects in localbody.', 'Full caller ordering and independent original reference remain incomplete.'),
        (0x9196,0x91d4,'Controlled terrain response dispatch','Default C4F2drag3000 and C4EEoverride0 before8728 rawtile query atcontrolledX/Y plusF268. AND2E00 minus2000 wordN guard; nonnegative selects oneof8 branchslots viaLSR7. AfterhandlercopyliveF268toF26A. Native entry bindsreferencesandrequiredhandlers.', 'Remaining terrain handlers, F268 producers/mutations, runtime frame binding and independent original reference remain incomplete.'),
        (0x91f4,0x920a,'Terrain response slot5','Literal C4F2=F0000, C4EE=8000; RTS. Native special slot5 preserves both long writes.', 'Terrain response reaching domains, native loop binding and independent original reference remain incomplete.'),
        (0x6796,0x6814,'Base player frame history','Only C444=1C6C records. Base C4E4 actor, cursor=(word6000+16)&03FF published before writes. Record words X/Y, word from6814+(selector70 LSR1 signed-word operand), direction bytes121/122, high speed words58/62, bytes118/120 and124 with bit0 removed if bit5 set. Byte15 retained. Native typed recorder preserves order and partial writes.', 'Selector table extent and all selector domains, cursor producer/alignment and history consumer bindings, independent original snapshots remain incomplete.'),
        (0x881c,0x8838,'Controlled airborne counter','Resolve C4E0. C524 nonzero or actor124 bit0 leaves68 unchanged; otherwise ADDQ.W1 wraps count. Native counter preserves ground/freeze gates.', 'Shared frame bindings and independent original-frame comparison remain incomplete.')]:
        cursor=start;evidence=[]
        while cursor<end:
            if cursor not in accepted:raise ValueError('Unaccepted boundary '+hex(cursor))
            i=Decoder(rom,cursor).decode();evidence.append(i);cursor+=i['size']
        if cursor!=end:raise ValueError('Range end mismatch')
        operations.append(dict(entry=f'{start:06X}',end_exclusive=f'{end:06X}',name=name,contract=contract,pending=pending,instruction_evidence=evidence))
    middle={0x7748,0x8c88,0x29ee,0xa808,0x785c,0x6796,0x881c,0x9196,0x8838,0x925c}
    frame=next(o for o in operations if o['entry']=='001C6C')
    calls=[dict(order=n+1,site=f'{i["address"]:06X}',target=f'{i["target"]:06X}',
            binding='Shared bounded middle; required service implementations/domains still apply' if i['target'] in middle else 'Outside shared middle; full-frame binding pending')
           for n,i in enumerate(i for i in frame['instruction_evidence'] if i['flow']=='call')]
    return dict(rom_sha256=ROM_HASH,operations=operations,normal_frame_calls=calls,
        normal_frame_call_counts=dict(total=len(calls),inside_shared_middle=sum(int(c['target'],16) in middle for c in calls),outside_shared_middle=sum(int(c['target'],16) not in middle for c in calls)),
        scroll_command_literals=dict(source='006A26',end_exclusive='006AA6',commands=scroll_commands,sha256=hashlib.sha256(rom[0x6a26:0x6aa6]).hexdigest()),
        native_sources=['src/core/player_frame_history.hpp','src/core/player_terrain_response.hpp','src/core/player_trigger_scan.hpp','src/core/player_trigger_pool.hpp','src/core/player_trigger_dispatch.hpp','src/core/player_post_motion.hpp','src/core/scheduled_player_frame.hpp','src/core/palette_flash.hpp','src/core/plane_scroll.hpp','src/core/actor_animation_list.hpp'],complete_mapping=False,world_integrated=False)
if __name__=='__main__':
    project=Path(__file__).resolve().parents[1]
    report=catalogue(project)
    (project/'docs/stage9/player-frame-history-contract.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
    with (project/'docs/stage9/normal-level-frame-calls.csv').open('w',newline='',encoding='utf-8-sig') as file:
        writer=csv.DictWriter(file,fieldnames=['order','site','target','binding']);writer.writeheader();writer.writerows(report['normal_frame_calls'])
    print(report['normal_frame_call_counts'])
